// Active risks from the ACAPS Risk Radar export, generated by scripts/build_reports.py, and
// the News feed built from them. Nothing here is written by hand except which risks count as
// the panel's region and the stats pulled from R1043's 30 Sep update; rerun the script if the
// export changes.

import exported from "../mocks/risk-radar-active.json"
import type { Article, Report } from "./types"

export const REPORTS = exported as Report[]

/** The risk this panel answers questions about. */
export const PANEL_RISK = "R1043"

/**
 * The panel's region: every active risk that covers Chad (R1043, and R1066 for the Lake Chad
 * Basin), plus R1055, filed under Sudan but about returns from eastern Chad into West Darfur.
 */
export const REGION = ["R1043", "R1066", "R1055"]

export const reportById = (id: string) => REPORTS.find((r) => r.id === id)!

/** Figures quoted in one update, shown as stat tiles when that update is open. */
export const STATS: Record<string, { value: string; label: string }[]> = {
  "R1043@2026-09-30": [
    { value: "400+", label: "refugees crossing each day" },
    { value: "20×", label: "the rate of previous months" },
    { value: "55,000+", label: "arrivals since January" },
  ],
}

/** ACAPS updates have no titles, but each opens with a one-sentence summary: use that. */
function splitLede(text: string) {
  const m = /^([\s\S]+?[a-z0-9)])\.\s+(?=[A-Z])/.exec(text)
  return m
    ? { headline: `${m[1]}.`, body: text.slice(m[0].length) }
    : { headline: text, body: "" }
}

/** When a risk went on the radar: the day its first trigger was entered. */
const addedOn = (r: Report) =>
  r.triggers
    .map((t) => t.entered)
    .filter((d): d is string => !!d)
    .sort()[0]

/** Every dated ACAPS post for the region, newest first. */
export const ARTICLES: Article[] = REGION.map(reportById)
  .flatMap((r) => {
    const added = addedOn(r)
    return [
      ...r.updates.map((u) => ({
        id: `${r.id}@${u.date}`,
        riskId: r.id,
        kind: "update" as const,
        date: u.date,
        ...splitLede(u.text),
        sources: u.sources,
      })),
      ...(added
        ? [
            {
              id: `${r.id}@${added}`,
              riskId: r.id,
              kind: "added" as const,
              date: added,
              headline: r.title,
              body: r.rationale,
              sources: r.rationaleSources,
            },
          ]
        : []),
    ]
  })
  .sort((a, b) => b.date.localeCompare(a.date))
